            atomicAdd(&G[(c * 3 + 2)], (skz * ((((H0_0 * R0_0_1_0) + (H0_1 * R1_0_1_0)) + (H0_2 * R0_1_1_0)) + (H0_3 * R0_0_2_0))));
        }
        // AtomicAdd: every record of every pair on an atom adds into that atom's row
        // of G
        atomicAdd(&G[(aa * 3 + 0)], (sk * gA0));
        atomicAdd(&G[(aa * 3 + 1)], (sk * gA1));
        atomicAdd(&G[(aa * 3 + 2)], (sk * gA2));
        atomicAdd(&G[(ab * 3 + 0)], (sk * gB0));
        atomicAdd(&G[(ab * 3 + 1)], (sk * gB1));
        atomicAdd(&G[(ab * 3 + 2)], (sk * gB2));
    }
}
